builder.Services.AddRateLimiter(options =>
{
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
    options.OnRejected = async (ctx, ct) =>
    {
        ctx.HttpContext.Response.Headers.RetryAfter =
            ctx.Lease.TryGetMetadata(MetadataName.RetryAfter, out var retry)
                ? ((int)retry.TotalSeconds).ToString() : "60";
        await ctx.HttpContext.Response.WriteAsJsonAsync(
            new { title = "Too many requests", status = 429 }, ct);
    };
    options.AddFixedWindowLimiter("fixed", o =>
    {
        o.PermitLimit = 100;
        o.Window = TimeSpan.FromMinutes(1);
        o.QueueLimit = 0;
    });
    options.AddSlidingWindowLimiter("sliding", o =>
    {
        o.PermitLimit = 100;
        o.Window = TimeSpan.FromMinutes(1);
        o.SegmentsPerWindow = 4;
    });
    options.AddConcurrencyLimiter("export", o => o.PermitLimit = 5);
});
app.UseRateLimiter();

options.GlobalLimiter = PartitionedRateLimiter.Create<HttpContext, string>(ctx =>
{
    var tenant = ctx.User.FindFirstValue("tenant_id")
        ?? ctx.Connection.RemoteIpAddress?.ToString()
        ?? "anonymous";
    return RateLimitPartition.GetSlidingWindowLimiter(tenant, _ => new SlidingWindowRateLimiterOptions
    {
        PermitLimit = 500,
        Window = TimeSpan.FromMinutes(1),
        SegmentsPerWindow = 6
    });
});

app.MapGet("/api/orders", GetOrders).RequireRateLimiting("sliding");

options.AddTokenBucketLimiter("mobile", o =>
{
    o.TokenLimit = 100;
    o.TokensPerPeriod = 20;
    o.ReplenishmentPeriod = TimeSpan.FromSeconds(1);
    o.AutoReplenishment = true;
});
app.MapGroup("/api/mobile").RequireRateLimiting("mobile");

options.OnRejected = async (context, token) =>
{
    var log = context.HttpContext.RequestServices
        .GetRequiredService<ILoggerFactory>().CreateLogger("RateLimit");
    log.LogWarning("Rate limit rejected Path={Path} Partition={Partition}",
        context.HttpContext.Request.Path,
        context.HttpContext.Items["RateLimitPartition"] ?? "unknown");
    context.HttpContext.Response.StatusCode = 429;
    await context.HttpContext.Response.WriteAsync("Rate limit exceeded.", token);
};
